const CACHE='english-lab-v13';
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(['./','./index.html','./fsrs.js','./review-core.js','./app.js','./vocab-data.js','./vocab-ui.js','./i18n.js','./ai.js','./news.js','./dictionary-ui.js','./ai-dictionary.js','./notebook.js','./settings.js','./library.js','./adaptive-game.js','./style.css','./i18n.css','./news.css','./vocab.css','./dictionary.css','./notebook.css','./settings.css','./library.css','./adaptive-game.css','./print.css','./icon.svg'])));self.skipWaiting()});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))));self.clients.claim()});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin||new URL(event.request.url).pathname.startsWith('/api/'))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request)))});
